import {TODAY} from './data.js?v=20260919-residents';

export const renovationSteps=['فحص المبنى','تحديد نطاق العمل','تحديد السكان المتأثرين','تجهيز الوحدات البديلة','نقل السكان','تنفيذ الصيانة','فحص الجودة','إعادة السكان'];
export const buildingRenovationSteps=['تقييم المبنى','إشعار السكان','تخصيص الوحدات البديلة','نقل السكان','تنفيذ التجديد','فحص الجودة','إعادة السكان'];
export const relocationSteps=['تم الإشعار','تخصيص الوحدة البديلة','الانتقال المؤقت','الصيانة جارية','فحص الوحدة','إعادة المستأجر'];
export const renovationLabels={PLANNING:['تخطيط','gray'],ASSESSMENT:['تقييم','blue'],RELOCATION:['نقل السكان','amber'],RENOVATION:['تحت الصيانة','amber'],INSPECTION:['فحص الجودة','blue'],RETURN:['إعادة السكان','green'],COMPLETED:['مكتمل','green']};
export const residentLabels={NOTIFIED:['تم الإشعار','blue'],ASSIGNED:['تم تخصيص الوحدة','amber'],RELOCATED:['تم نقل المستأجر','blue'],READY:['جاهز للعودة','green'],RETURNED:['تمت إعادة المستأجر','green']};
export function initializeRenovation(d){
  for(const u of d.units)u.usageType='RENTAL';
  const pool=d.units.filter(u=>u.status==='VACANT'&&['A09','A10','A11','A12'].includes(u.buildingId)).slice(0,54).map(u=>({unitId:u.id,state:'READY',residentId:null}));
  pool.forEach(p=>{d.units.find(u=>u.id===p.unitId).usageType='TEMPORARY_HOUSING';});
  const originalTenants=[...d.tenants.filter(t=>t.unitId.startsWith('A01-')).slice(0,25),...d.tenants.filter(t=>t.unitId.startsWith('A02-')).slice(0,21)];
  const featured=originalTenants.findIndex(t=>t.name==='خالد محمد');originalTenants.unshift(...originalTenants.splice(featured,1));
  let used=0,returned=0;
  const residents=originalTenants.map((t,i)=>{
    const status=i<14?'RELOCATED':i<31?'RETURNED':i<33?'ASSIGNED':'NOTIFIED';
    const buildingId=t.unitId.split('-')[0];const rec={id:'REL-'+(3001+i),tenantId:t.id,buildingId,originalUnitId:t.unitId,temporaryUnitId:'',status,moveDate:i<31?'2026-09-03':null,expectedReturn:buildingId==='A01'?'2026-10-20':'2026-10-31',actualReturn:status==='RETURNED'?'2026-09-14':null,reason:buildingId==='A01'?'تجديد داخلي وعزل دورات المياه':'معالجة الواجهات والعزل',inspectionPassed:status==='RETURNED',history:[{text:'تم إشعار الأسرة بخطة التجديد',date:'2026-09-01',by:'منسق السكان'}]};
    if(status==='RELOCATED'||status==='ASSIGNED'){const p=pool[used++];p.state=status==='RELOCATED'?'USED':'RESERVED';p.residentId=rec.id;rec.temporaryUnitId=p.unitId;}
    if(status==='RETURNED')rec.temporaryUnitId=pool[16+returned++].unitId;
    if(status!=='NOTIFIED')rec.history.push({text:'تم تخصيص الوحدة البديلة '+rec.temporaryUnitId,date:'2026-09-02',by:'منسق السكان'});
    if(['RELOCATED','RETURNED'].includes(status))rec.history.push({text:'تم الانتقال إلى السكن المؤقت',date:'2026-09-03',by:'فريق الانتقال'},{text:'بدأت أعمال التجديد في الوحدة الأصلية',date:'2026-09-04',by:'مشرف التجديد'});
    if(status==='RETURNED')rec.history.push({text:'اجتازت الوحدة الأصلية فحص الجودة',date:'2026-09-13',by:'فريق الجودة'},{text:'تمت إعادة الأسرة وتسليم الوحدة الأصلية',date:'2026-09-14',by:'منسق السكان'});
    return rec;
  });
  const plans=d.buildings.map((b,i)=>({id:b.id,buildingId:b.id,status:i<2?'RENOVATION':'PLANNING',progress:i===0?68:i===1?52:0,weight:i<2?.2:.06,phase:Math.floor(i/2)+1,start:['2026-09-01','2026-09-01','2026-11-01','2026-11-01','2027-01-01','2027-01-01','2027-03-01','2027-03-01','2027-05-01','2027-05-01','2027-07-01','2027-07-01'][i],end:['2026-10-20','2026-10-31','2026-12-31','2026-12-31','2027-02-28','2027-02-28','2027-04-30','2027-04-30','2027-06-30','2027-06-30','2027-08-31','2027-08-31'][i],type:['تجديد داخلي وعزل','واجهات وعزل','تجديد داخلي','عزل الأسطح','أعمال إنشائية','تجديد شامل','واجهات','تجديد داخلي','عزل','أعمال إنشائية','تجديد شامل','واجهات'][i],manager:i%2===0?'المهندس عبدالله سالم':'المهندس ماجد ناصر',scope:i===0?'تحديث دورات المياه والمطابخ، معالجة العزل، وتجديد التشطيبات الداخلية على دفعات من الوحدات.':i===1?'معالجة الواجهات وعزل الأسطح ومناطق التسرب، مع فصل مواقع العمل عن مناطق السكن.':'تحديد نطاق الأعمال التفصيلي بعد فحص المبنى، مع جدولة التنفيذ وفق جاهزية السكن المؤقت.'}));
  return {plans,residents,pool};
}
export function renovationMetrics(d,buildingId){const all=d.renovation,rs=all.residents.filter(r=>!buildingId||r.buildingId===buildingId),plans=all.plans.filter(p=>!buildingId||p.buildingId===buildingId);return {planned:plans.length,underWork:plans.filter(p=>p.status==='RENOVATION').length,affected:rs.length,moved:rs.filter(r=>['RELOCATED','READY','RETURNED'].includes(r.status)).length,current:rs.filter(r=>['RELOCATED','READY'].includes(r.status)).length,pending:rs.filter(r=>['NOTIFIED','ASSIGNED'].includes(r.status)).length,readyToReturn:rs.filter(r=>r.status==='READY').length,returned:rs.filter(r=>r.status==='RETURNED').length,poolTotal:all.pool.length,poolUsed:all.pool.filter(p=>p.state==='USED').length,poolReady:all.pool.filter(p=>p.state==='READY').length,poolReserved:all.pool.filter(p=>p.state==='RESERVED').length,progress:buildingId?plans[0]?.progress||0:Math.round(plans.reduce((sum,p)=>sum+p.progress*p.weight,0))};}
export function assignTemporaryUnit(d,residentId,unitId){const r=d.renovation.residents.find(r=>r.id===residentId),p=d.renovation.pool.find(p=>p.unitId===unitId);if(!r||r.status!=='NOTIFIED')throw new Error('هذه الأسرة لديها تخصيص قائم بالفعل.');if(!p||p.state!=='READY')throw new Error('الوحدة المختارة غير متاحة حالياً.');p.state='RESERVED';p.residentId=r.id;r.temporaryUnitId=p.unitId;r.status='ASSIGNED';r.history.push({text:'تم تخصيص الوحدة البديلة '+p.unitId,date:TODAY,by:'منسق السكان'});return r;}
export function confirmRelocation(d,residentId){const r=d.renovation.residents.find(r=>r.id===residentId);if(!r||r.status!=='ASSIGNED')throw new Error('خصص وحدة بديلة قبل تأكيد الانتقال.');const p=d.renovation.pool.find(p=>p.residentId===r.id);if(!p||p.state!=='RESERVED')throw new Error('تعذر العثور على حجز الوحدة البديلة.');p.state='USED';r.status='RELOCATED';r.moveDate=TODAY;r.history.push({text:'تم تأكيد انتقال الأسرة وتسليم السكن المؤقت',date:TODAY,by:'فريق الانتقال'});return r;}
export function approveRenovation(d,buildingId){const p=d.renovation.plans.find(p=>p.id===buildingId),rs=d.renovation.residents.filter(r=>r.buildingId===buildingId);if(!p||p.status!=='RENOVATION')throw new Error('المبنى ليس في مرحلة تنفيذ التجديد.');if(rs.some(r=>['NOTIFIED','ASSIGNED'].includes(r.status)))throw new Error('أكمل انتقال الأسر المتأثرة قبل اعتماد اكتمال أعمال المبنى.');p.status='INSPECTION';p.progress=90;return p;}
export function approveInspection(d,buildingId){const p=d.renovation.plans.find(p=>p.id===buildingId);if(!p||p.status!=='INSPECTION')throw new Error('يجب اعتماد اكتمال الأعمال أولاً.');p.status='RETURN';p.progress=95;for(const r of d.renovation.residents.filter(r=>r.buildingId===buildingId&&r.status==='RELOCATED')){r.status='READY';r.inspectionPassed=true;r.history.push({text:'اجتازت الوحدة الأصلية فحص الجودة وأصبحت جاهزة للعودة',date:TODAY,by:'فريق الجودة'});}return p;}
export function confirmReturn(d,residentId){const r=d.renovation.residents.find(r=>r.id===residentId);if(!r||r.status!=='READY'||!r.inspectionPassed)throw new Error('يجب اجتياز فحص الجودة قبل عودة الأسرة.');const p=d.renovation.pool.find(p=>p.residentId===r.id);if(!p||p.state!=='USED')throw new Error('لا توجد وحدة مؤقتة مستخدمة لهذه الأسرة.');p.state='READY';p.residentId=null;r.status='RETURNED';r.actualReturn=TODAY;r.history.push({text:'تمت إعادة الأسرة واستلام الوحدة المؤقتة',date:TODAY,by:'منسق السكان'});const plan=d.renovation.plans.find(p=>p.id===r.buildingId);if(d.renovation.residents.filter(x=>x.buildingId===r.buildingId).every(x=>x.status==='RETURNED')){plan.status='COMPLETED';plan.progress=100;}return r;}
